{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01", "C04", "C17", "C21", "C128", "C133", "C144", "C146", "C160", "C162", "C165"],
  "contradictory_card_ids": ["C155", "C170"],
  "prediction_basis_card_ids": ["C01", "C04", "C17", "C21", "C128", "C144", "C160", "C165"],
  "claims": [
    {
      "claim": "L4 Caco-2 records for close structural analogues show high permeability: diphenhydramine A-B 39.0 and B-A 38.7 x10^-6 cm/s with no efflux, pheniramine A-B 42.9 and B-A 39.8, and a benzhydryl amide 7l A-B 44.1 x10^-6 cm/s.",
      "card_ids": ["C144", "C160", "C165", "C128"]
    },
    {
      "claim": "Loperamide, the main amide-amine cautionary analogue, shows high intrinsic permeability but mixed efflux results (B-A 42.7 vs A-B 8.77 at 1 uM in C155 and C170, but efflux ratio 0.8 at 10 uM in C168), so a P-gp-driven low F is not affirmatively established for the query.",
      "card_ids": ["C133", "C155", "C162", "C168", "C170"]
    },
    {
      "claim": "L4 records for acids and zwitterions (ketoprofen, warfarin, fexofenadine, cephalexin) concern different scaffolds and do not bear on the query's lipophilic basic amine class.",
      "card_ids": ["C124", "C129", "C137", "C140", "C167"]
    },
    {
      "claim": "L4 supports the absorption component only and is consistent with transferable human absolute F values above 20% for diphenhydramine, dapoxetine, trimipramine, and milnacipran.",
      "card_ids": ["C01", "C04", "C17", "C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C128", "C133", "C144", "C146", "C155", "C160", "C162", "C165", "C168", "C170"]
    }
  ],
  "evidence_gaps": [
    "No direct F measurement for the query in any level.",
    "No query-specific solubility, permeability, or efflux data; L4 records are for analogues.",
    "Loperamide efflux data are mixed and assay dependent, so P-gp liability for the query is unmeasured.",
    "No first-pass metabolism data for the query's tertiary amide.",
    "Low neutral fraction 0.28 and high logP leave dissolution and ionization uncertainty."
  ],
  "decision_summary": "Keep high and strengthen: L4 adds high Caco-2 permeability for close lipophilic basic amine and amide analogues with no consistent efflux, reinforcing the absorption component. Combined with transferable human absolute F values above 20% for the same class, F>=20% remains better supported. Confidence stays moderate because no direct query PK exists and loperamide-like efflux cannot be excluded."
}

